{
  "interpretation": {
    "name": "Line1NutrunnerTighteningWithReturn",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring the shared nutrunner NR7 to station st1, tighten the fasteners of variant F25 according to the MES program, evaluate and record the result, then return the tool to the crib and release it.",
    "constraints": [
      "NR7 must be reserved before use and released after it has been returned to the crib",
      "The lease is renewed by every tool-using Step through dependency on reserve-tool",
      "transport-tool must be executed by agvexecutor",
      "NR7 must be at the station before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program, with no numeric process values in the Recipe",
      "The tightening must be evaluated and recorded for traceability",
      "NR7 must be returned to the crib after the tightening"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "one-off, for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-nr7-tightening-f25",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["fasten"],
            "dep": ["program", "reserve", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "fasten",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve", "transport-to-station"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["fasten", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["fasten"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": "finish",
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
